fn explicit_double(x: Int) -> Int {
  return x * 2;
}

fn tail_double(x: Int) -> Int {
  x * 2
}

fn say_hello(name: Str) {
  io.println("Hello, " + name + "!");
}

fn main() -> Int {
  let a = explicit_double(21);
  let b = tail_double(21);
  say_hello("Kilo");
  return a + b;
}
